import * as T from './vendor/three.module.js';
// A shared distance field makes raiders walk around city blocks instead of pushing into walls.
export function cityNavigation(free){let cells=null,distances=null,last=-1;const size=2,w=111,h=111,x0=2290,z0=-233,index=(x,z)=>Math.max(0,Math.min(h-1,Math.round((z-z0)/size)))*w+Math.max(0,Math.min(w-1,Math.round((x-x0)/size))),adjacent=i=>[i%w?i-1:-1,i%w<w-1?i+1:-1,i>=w?i-w:-1,i<w*(h-1)?i+w:-1].filter(i=>i>=0);
 return function route(n,target){if(!cells){cells=new Uint8Array(w*h);for(let z=0;z<h;z++)for(let x=0;x<w;x++)cells[z*w+x]=free(x0+x*size,z0+z*size,.45)?1:0}let goal=index(target.x,target.z);if(!cells[goal])goal=adjacent(goal).find(i=>cells[i])??goal;if(goal!==last){last=goal;distances=new Int32Array(w*h).fill(-1);const queue=[goal];distances[goal]=0;for(let at=0;at<queue.length;at++)for(const j of adjacent(queue[at]))if(cells[j]&&distances[j]<0){distances[j]=distances[queue[at]]+1;queue.push(j)}}const current=index(n.g.position.x,n.g.position.z);if(distances[current]<=2)return target;const next=adjacent(current).filter(i=>cells[i]&&distances[i]>=0).sort((a,b)=>distances[a]-distances[b])[0];if(next===undefined)return target;return new T.Vector3(x0+(next%w)*size,0,z0+Math.floor(next/w)*size)};
}
